var findLexSmallestString = function(s, a, b) {
    const visited = new Set([s]);
    const q = [s];
    let best = s;
    const n = s.length;
    while (q.length > 0) {
        const curr = q.shift();
        if (curr < best) best = curr;
        const arr = curr.split('');
        for (let i = 1; i < n; i += 2) {
            arr[i] = String((Number(arr[i]) + a) % 10);
        }
        const added = arr.join('');
        if (!visited.has(added)) {
            visited.add(added);
            q.push(added);
        }
        const rotated = curr.slice(n - b) + curr.slice(0, n - b);
        if (!visited.has(rotated)) {
            visited.add(rotated);
            q.push(rotated);
        }
    }
    return best;
};
